INSERT INTO feature VALUES('record-update','types','Record update','records','implemented','ordinary',NULL,'`#{b | l = a, …}` is the base''s record with each written field at its written type — a label the base lacks extends it, one at another type retypes it — and the base''s other fields kept, each read off the base; a computation written as the base runs first, and a base of another shape is refused at the base. Written in a type, an update stands for the record it builds, an update of an update keeping the inner record''s own fields, so the type prints as that record and reads back.','surface-lowering core-checker core-term','corpus/model/records/record-update.gandr corpus/model/records/record-extend.gandr corpus/model/records/record-update-field-retype.gandr corpus/model/records/record-update-of-a-call.gandr corpus/model/records/nested-record-update.gandr corpus/model/records/value-semantics-no-aliasing.gandr corpus/model/records/record-update-in-a-type.gandr corpus/pathological/records/record-update-non-record.gandr corpus/pathological/records/record-update-stale-type.gandr corpus/pathological/records/shared-then-updated.gandr corpus/pathological/records/wide-record-update.gandr corpus/pathological/records/deep-record-update-cost.gandr crates/surface-dispatcher/src/typed.rs','corpus/model/records/record-extend.gandr corpus/model/records/record-update-field-retype.gandr',NULL);
